        c = _c;
    }

    function run(uint256 amt, address to) public payable {
        require(amt > 0, "amount must be positive");

        // Grant maximal allowance so the transferFrom can succeed whenever
        // this contract actually holds mAsset tokens.
        IERC20 tok = IERC20(c.mAsset());
        try tok.approve(address(c), type(uint256).max) {
            // approval granted (or ignored)
        } catch {
            // token rejected approval; supplyTokenTo may then revert
        }

        uint256 balanceBefore = c.balanceOfToken(to);

        bool reverted;
        try c.supplyTokenTo(amt, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.balanceOfToken(to);

        // General rule: a successful supplyTokenTo with amt > 0 must strictly
        // increase the credited mAsset balance of the beneficiary `to`.
        assert(reverted || balanceAfter > balanceBefore);
    }

    receive() external payable {}
}

